                        }

                        if (item.keyForList === selectedTaxRate) {
                            Navigation.goBack(ROUTES.WORKSPACE_CATEGORY_SETTINGS.getRoute(policyID, categoryName));
                            return;
                        }

                        Category.setPolicyCategoryTax(policyID, categoryName, item.keyForList);
